+@page "/board"
+@using static sv_f98c0f62ed754c9795e71b2a522c3e72.Components.Pages.Board.KanbanColumn
+@rendermode InteractiveServer
+@inject ITaskService TaskService
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h3 class="mb-3">Kanban Board</h3>
+
+@if (isLoading)
+{
+    <div class="d-flex justify-content-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @errorMessage
+        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="LoadTasks">Retry</button>
+    </div>
+}
+else
+{
+    <BoardStats TotalCount="allTasks.Count"
+                ToDoCount="GetTasksForStatus(StatusToDo).Count"
+                InProgressCount="GetTasksForStatus(StatusInProgress).Count"
+                DoneCount="GetTasksForStatus(StatusDone).Count"
+                OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />
+
+    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />
+
+    <div class="row g-3">
+        <KanbanColumn ColumnName="To Do"
+                      Tasks="GetFilteredTasksForStatus(StatusToDo)"
+                      CanMoveLeft="false"
+                      CanMoveRight="true"
+                      OnMoveTask="HandleMoveTask"
+                      OnAddTask="args => HandleAddTask(StatusToDo, args)" />
+
+        <KanbanColumn ColumnName="In Progress"
+                      Tasks="GetFilteredTasksForStatus(StatusInProgress)"
+                      CanMoveLeft="true"
+                      CanMoveRight="true"
+                      OnMoveTask="HandleMoveTask"
+                      OnAddTask="args => HandleAddTask(StatusInProgress, args)" />
+
+        <KanbanColumn ColumnName="Done"
+                      Tasks="GetFilteredTasksForStatus(StatusDone)"
+                      CanMoveLeft="true"
+                      CanMoveRight="false"
+                      OnMoveTask="HandleMoveTask"
+                      OnAddTask="args => HandleAddTask(StatusDone, args)" />
+    </div>
+}
+
+@code {
+    private const string StatusToDo = "To Do";
+    private const string StatusInProgress = "In Progress";
+    private const string StatusDone = "Done";
+
+    private static readonly string[] Statuses = [StatusToDo, StatusInProgress, StatusDone];
+
+    private List<TaskItem> allTasks = new();
+    private string searchText = string.Empty;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetTasksForStatus(string status) =>
+        allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredTasksForStatus(string status) =>
+        allTasks
+            .Where(t => t.Status == status)
+            .Where(t => string.IsNullOrEmpty(searchText)
+                || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+    private void HandleSearchChanged(string text)
+    {
+        searchText = text;
+    }
+
+    private async Task HandleMoveTask((int TaskId, MoveDirection Direction) args)
+    {
+        var task = allTasks.FirstOrDefault(t => t.Id == args.TaskId);
+        if (task is null) return;
+
+        var currentIndex = Array.IndexOf(Statuses, task.Status);
+        var newIndex = args.Direction == MoveDirection.Left ? currentIndex - 1 : currentIndex + 1;
+        if (newIndex < 0 || newIndex >= Statuses.Length) return;
+
+        var newStatus = Statuses[newIndex];
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            // Update local state
+            var idx = allTasks.IndexOf(task);
+            allTasks[idx] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task HandleAddTask(string status, (string Title, string Assignee, string Priority, DateTime DueDate) formData)
+    {
+        try
+        {
+            var newTask = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
+            // CreateTaskAsync may not set the status to the column's status, so adjust
+            allTasks.Add(newTask with { Status = status });
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
+

